/* Engineering episode: an original teaching model, grounded in the supplied career materials. */
(() => {
 'use strict';
 const key='ochakovo-engineering-story-v1';
 const steps=[
 ['welcome','factory','Другой формат. Та же точность','Сегодня линия переходит на более широкую банку. Разберёмся, что нужно изменить, чтобы оборудование работало согласованно.','Начни смену вместе со мной.'],
 ['tour','factory','Познакомься с узлом','Направляющие удерживают тару на пути. Датчик замечает её появление, а привод двигает ленту. Нажми на три детали и узнай их роль.','Исследуй три отмеченных узла.'],
 ['order','bench','Сначала — задание','Банка стала шире. Важно сопоставить новый формат с оснасткой и программой: одна механическая регулировка не решает всю задачу.','Выбери тару из нового задания: формат Б.'],
 ['baseline','factory','Проверь свою гипотезу','На виртуальной модели посмотрим, что произойдёт с новой банкой при прежней настройке. На настоящем участке такие проверки выполняют по утверждённому порядку.','Запусти модель и проследи за банкой.'],
 ['locate','factory','Что мешает проходу?','Банка упирается на входе. Лента движется, датчик видит тару. Найди деталь, геометрия которой не подходит новому формату.','Выбери узел прямо на модели.'],
 ['prepare','factory','Подготовка к переналадке','На работающую линию не вмешиваются. Подготовку оборудования и допуск организует наставник. Для следующего шага он передаст тебе безопасный учебный макет.','Попроси наставника подготовить макет.'],
 ['tooling','bench','Подбери оснастку','У двух комплектов разная ширина прохода. Сопоставь их с широкой банкой и маркировкой задания. Наладчик подбирает оснастку под конкретный формат.','Выбери комплект Б.'],
 ['install','bench','Деталь должна встать на место','Оснастка выбрана. На учебном макете совмести направляющие с посадочными местами. За крепление и проверку готовности отвечает наставник.','Установи выбранный комплект на макет.'],
 ['gap','bench','Оставь место для прохода','Слишком узко — банка застрянет. Слишком широко — потеряет направление. Выставь зазор по карточке учебного задания.','Учебная шкала: рабочая отметка — 4.'],
 ['chain','control','Как оборудование понимает команду','Автоматика связывает наблюдение и движение. Датчик обнаруживает банку, контроллер обрабатывает сигнал, привод выполняет команду.','Собери путь сигнала, нажимая на устройства по порядку.'],
 ['recipe','control','Механика и программа — одна задача','Направляющие уже рассчитаны на формат Б. Теперь выбери для него задание на учебном терминале. Настройка должна соответствовать установленной оснастке.','Выбери формат Б и примени задание.'],
 ['dry','factory','Сначала — без продукции','Наставник проверил сборку и готовность. Посмотри пробный цикл без банок: лента должна двигаться, а узел — завершить цикл без остановки.','Проведи проверку пустого узла.'],
 ['test','factory','Теперь — пробный проход','Пустой цикл прошёл. Проверим три учебные банки: каждая должна пройти между направляющими, а датчик — отметить каждую.','Запусти пробный проход и наблюдай за счётчиком.'],
 ['inspect','factory','Число — ещё не весь результат','Три сигнала получены. Но инженер также проверяет, как прошла тара: без застревания, перекоса и повреждения. Осмотри каждую банку на выходе.','Нажми на три банки, чтобы проверить результат.'],
 ['record','control','Передай понятный результат','Команде нужно знать, что изменили и чем подтвердили результат. Запиши формат, настройку и проверку. «Всё хорошо» не поможет следующей смене.','Выбери запись, по которой можно восстановить ход работы.'],
 ['finish','factory','Ты связал механику и автоматику','Ты сопоставил тару и оснастку, настроил учебный узел, разобрал путь сигнала и подтвердил результат проверкой. Так из отдельных действий складывается инженерная задача.','В материалах «Очаково» есть работа с инженером, оцифровка линии и поиск улучшений.']
 ];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const btn=(a,t,cls='')=>`<button type="button" class="es-button ${cls}" data-es="${a}">${t}</button>`;
 const can=(x,y,wide=true,n='',extra='')=>`<g transform="translate(${x} ${y})" ${extra}><ellipse cx="0" cy="91" rx="39" ry="10" fill="#243d4520"/><path d="M${wide?-30:-23} 0 Q0 -10 ${wide?30:23} 0 L${wide?33:26} 78 Q0 94 ${wide?-33:-26} 78Z" fill="${wide?'#bd493b':'#467f86'}" stroke="#344e56" stroke-width="3"/><path d="M${wide?-28:-21} 20 Q0 30 ${wide?28:21} 20V60Q0 72 ${wide?-28:-21} 60Z" fill="#fff3cf"/><path d="M-16 28v25" stroke="#fff" stroke-width="5" opacity=".6"/><ellipse cx="0" cy="0" rx="${wide?30:23}" ry="9" fill="#ced8d2" stroke="#344e56" stroke-width="3"/><ellipse cx="3" cy="0" rx="9" ry="4" fill="#849a99"/><text x="0" y="51" text-anchor="middle" fill="#344e56" font-size="23" font-weight="800">${n|| (wide?'Б':'А')}</text></g>`;
 const target=(action,label,svg)=>`<g class="es-target" data-es="${action}" role="button" tabindex="0" aria-label="${label}"><title>${label}</title>${svg}</g>`;
 const svg=(body,cls='')=>`<svg class="es-art ${cls}" viewBox="0 0 1000 540" xmlns="http://www.w3.org/2000/svg" aria-label="Учебная модель оборудования">${body}</svg>`;
 function machine(s){
  const tour=s.step===1,locate=s.step===4,inspect=s.step===13,passed=s.step>=12,wide=s.step>=8;
  const interact=(a,label,body)=>tour||locate?target(a,label,body):`<g>${body}</g>`;
  return svg(`<ellipse cx="510" cy="475" rx="425" ry="40" fill="#243d4528"/>
   <path d="M150 310v145h40V325M770 310v145h40V325" fill="#527d7e" stroke="#344e56" stroke-width="5"/>
   <path d="M100 265L804 225 925 332 207 389Z" fill="#b7c7be" stroke="#344e56" stroke-width="4"/>
   <path d="M100 265v57l107 114v-47M207 389l718-57v51l-718 53Z" fill="#5b9093" stroke="#344e56" stroke-width="4"/>
   <path d="M125 268L800 244 895 326 213 368Z" fill="#879c98" stroke="#344e56" stroke-width="3"/>
   <g class="es-belt">${Array.from({length:17},(_,i)=>`<path d="M${140+i*39} ${268-i*1.3}l80 86" stroke="#b8c7bd" stroke-width="4"/>`).join('')}</g>
   ${interact('motor','Привод',`<g class="es-motor"><path d="M726 361l67-7 19 34-65 10Z" fill="#3d5964" stroke="#263e48" stroke-width="4"/><ellipse cx="769" cy="394" rx="41" ry="34" fill="#c5d0c6" stroke="#344e56" stroke-width="4"/><circle cx="769" cy="394" r="24" fill="#537c80"/><g class="es-wheel"><path d="M752 394h34m-17-17v34" stroke="#c5d0c6" stroke-width="5"/></g></g>${tour||locate?'<circle cx="818" cy="418" r="18" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="818" y="425" text-anchor="middle" font-size="21" fill="#b94337">3</text>':''}`)}
   <g class="es-cans">${s.step===3?can(250,211,true,'','class="es-moving-can"'):s.step===4?can(385,202):s.step===12?'':s.step===13? [640,740,840].map((x,i)=>target('can'+i,'Осмотреть банку '+(i+1),can(x,210,true,s.checked.includes('can'+i)?'✓':String(i+1)))).join(''):s.step===0||s.step===1?can(260,211,false)+can(380,206,false):''}</g>
   ${interact('guides','Направляющие',`<g class="es-guides"><rect x="420" y="205" width="335" height="145" fill="#fff" opacity="0"/><path d="M430 ${wide?227:248}L715 ${wide?216:237}v14L430 ${wide?241:262}Z" fill="#ede5cd" stroke="#344e56" stroke-width="4"/><path d="M440 ${wide?329:302}L725 ${wide?316:289}v15L440 ${wide?344:317}Z" fill="#d4cbb4" stroke="#344e56" stroke-width="4"/><path d="M470 237v-36m210 28v-34M480 335v33m210-42v28" stroke="#344e56" stroke-width="7"/></g>${tour||locate?'<circle cx="550" cy="194" r="18" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="550" y="201" text-anchor="middle" font-size="21" fill="#b94337">1</text>':''}`)}
   ${interact('sensor','Датчик',`<path d="M605 210v-64h36v66" fill="#8aaba6" stroke="#344e56" stroke-width="4"/><rect x="591" y="142" width="65" height="38" rx="7" fill="#344e56"/><circle class="es-sensor-light" cx="620" cy="162" r="10" fill="${passed?'#a4cb93':'#eac871'}"/>${tour||locate?'<circle cx="679" cy="153" r="18" fill="#fff7df" stroke="#b94337" stroke-width="3"/><text x="679" y="160" text-anchor="middle" font-size="21" fill="#b94337">2</text>':''}`)}
   <path d="M340 395l140-12v35l-140 11Z" fill="#f5edda"/><text x="410" y="414" text-anchor="middle" fill="#344e56" font-size="17" font-weight="800" transform="rotate(-4 410 414)">УЧЕБНЫЙ УЗЕЛ</text>
   ${s.step===12?'<g transform="translate(785 125)"><rect width="116" height="64" rx="8" fill="#344e56"/><text class="es-counter" x="58" y="42" text-anchor="middle" font-size="30" fill="#f7efd9">0 / 3</text></g>':''}`);
 }
 function bench(s){
  if(s.step===2)return svg(`<ellipse cx="500" cy="436" rx="310" ry="35" fill="#344e561c"/>${target('formatA','Формат А — прежняя узкая банка',`<g transform="translate(325 220) scale(1.75)">${can(0,0,false)}</g>`)}${target('formatB','Формат Б — новая широкая банка',`<g transform="translate(665 220) scale(1.75)">${can(0,0,true)}</g>`)}<text x="325" y="443" text-anchor="middle" fill="#344e56" font-size="22" font-weight="800">Формат А</text><text x="665" y="443" text-anchor="middle" fill="#344e56" font-size="22" font-weight="800">Формат Б</text>`);
  const kit=(x,wide,label)=>`<g transform="translate(${x} 265)"><path d="M-125-25h250v120h-250Z" fill="#d6cdb5" stroke="#344e56" stroke-width="3"/><path d="M-105-5h210v15h-210ZM-105 ${wide?65:35}h210v15h-210Z" fill="#eff0dc" stroke="#344e56" stroke-width="4"/><circle cx="-85" cy="3" r="4" fill="#547376"/><circle cx="85" cy="3" r="4" fill="#547376"/><text x="0" y="125" text-anchor="middle" fill="#344e56" font-size="24" font-weight="800">Комплект ${label}</text></g>`;
  if(s.step===6)return svg(`${can(500,160,true)}${target('kitA','Комплект А — узкий',kit(250,false,'А'))}${target('kitB','Комплект Б — широкий',kit(750,true,'Б'))}`);
  return svg(`<ellipse cx="500" cy="444" rx="320" ry="33" fill="#344e5620"/><path d="M180 242h640l-50 190H230Z" fill="#a7bcb3" stroke="#344e56" stroke-width="4"/><path d="M230 432h540v27H230Z" fill="#5e8988" stroke="#344e56" stroke-width="4"/><path d="M300 280h400M300 380h400" stroke="#557d7d" stroke-width="4" stroke-dasharray="8 10"/>${can(500,264,true)}<g class="es-assembly" ${s.step===7?'transform="translate(0 -95)"':''}><path d="M295 278h410v15H295Z" fill="#f4ecd7" stroke="#344e56" stroke-width="4"/><path class="es-front-guide" d="M295 ${s.step===8?310+s.gap*12:374}h410v15H295Z" fill="#e3dbc2" stroke="#344e56" stroke-width="4"/><circle cx="315" cy="285" r="5" fill="#637c7d"/><circle cx="685" cy="285" r="5" fill="#637c7d"/></g>`);
 }
 function terminal(s){
  if(s.step===9){const labels=[['drive','Привод','Двигает'],['sensor','Датчик','Обнаруживает'],['controller','Контроллер','Принимает решение']];return `<div class="es-chain"><div class="es-signal-path">${[0,1,2].map((_,i)=>`<span class="${s.chain[i]?'is-filled':''}">${s.chain[i]?({sensor:'Датчик',controller:'Контроллер',drive:'Привод'})[s.chain[i]]:i+1}</span>`).join('<b>→</b>')}</div><div class="es-components">${labels.map(([id,name,verb],i)=>`<button class="es-component" data-es="${id}" ${s.chain.includes(id)?'disabled':''}><svg viewBox="0 0 160 120" aria-hidden="true">${i===0?'<rect x="25" y="35" width="110" height="65" rx="12" fill="#638d8c"/><circle cx="80" cy="65" r="32" fill="#d9dfcc"/><path d="M60 65h40m-20-20v40" stroke="#344e56" stroke-width="7"/>':i===1?'<path d="M65 95V30h35v65" fill="#9eb7ad"/><rect x="40" y="20" width="80" height="50" rx="7" fill="#344e56"/><circle cx="80" cy="45" r="14" fill="#ecc16a"/>':'<rect x="20" y="15" width="120" height="90" rx="8" fill="#d7deca" stroke="#344e56" stroke-width="4"/><rect x="40" y="32" width="80" height="35" fill="#4e7d7d"/><path d="M40 85h80" stroke="#b7483b" stroke-width="9"/>'}</svg><strong>${name}</strong><small>${verb}</small></button>`).join('')}</div></div>`;}
  const body=s.step===10?`<p class="es-screen-label">ЗАДАНИЕ НА ПЕРЕНАЛАДКУ</p><h2>Формат тары</h2><div class="es-recipes">${btn('recipeA','А <small>Узкая банка</small>','es-recipe')}${btn('recipeB','Б <small>Широкая банка</small>','es-recipe')}</div><p>Установлено: комплект Б · зазор 4</p>`:s.step===14?`<p class="es-screen-label">ЖУРНАЛ ПЕРЕНАЛАДКИ · СМЕНА 01</p><h2>Что передадим команде?</h2>${btn('recordBad','Линия готова, всё хорошо.','es-record-option')}${btn('recordGood','Формат Б · комплект Б · зазор 4.<br>Пустой цикл пройден. Три банки прошли без замечаний.','es-record-option')}`:'';
  return `<div class="es-terminal"><div class="es-display">${body}</div><div class="es-terminal-foot"><span></span>УЧЕБНЫЙ ТЕРМИНАЛ</div></div>`;
 }
 function mount(host,{onComplete=()=>{}}={}){
  let s={step:0,checked:[],chain:[],gap:2},busy=false,disposed=false,animations=[],timers=[],paused=false;
  try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Number.isInteger(saved.step)&&saved.step>=0&&saved.step<steps.length){s={step:saved.step,checked:Array.isArray(saved.checked)?saved.checked.filter(x=>typeof x==='string'):[],chain:Array.isArray(saved.chain)?saved.chain.filter(x=>['sensor','controller','drive'].includes(x)):[],gap:[1,2,3,4,5,6].includes(saved.gap)?saved.gap:2};}}catch{}
  const save=()=>{try{localStorage.setItem(key,JSON.stringify(s));}catch{}};
  const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||window.GameMotion?.enabled()===false;
  const tell=t=>{const n=host.querySelector('.es-feedback');if(n)n.textContent=t;};
  function cancel(){animations.forEach(a=>a.cancel());animations=[];timers.forEach(clearTimeout);timers=[];busy=false;}
  function advance(){if(disposed)return;cancel();s.step=Math.min(15,s.step+1);s.checked=[];save();render(true);}
  function motion(el,frames,duration,delay=0){if(!el)return;const a=el.animate(frames,{duration:reduced()?1:duration,delay:reduced()?0:delay,fill:'forwards',easing:'ease-in-out'});animations.push(a);return a;}
  async function run(action){if(busy)return;busy=true;host.querySelectorAll('.es-actions button').forEach(b=>b.disabled=true);let end=[];
   if(action==='baseline'){end=[motion(host.querySelector('.es-moving-can'),[{transform:'translate(250px,211px)'},{transform:'translate(385px,202px)'}],1800)];tell('На входе банка упёрлась в направляющие.');}
   if(action==='install'){end=[motion(host.querySelector('.es-assembly'),[{transform:'translateY(-95px)'},{transform:'translateY(0px)'}],1100)];tell('Направляющие совмещены. Наставник проверяет крепление.');}
   if(action==='dry'){end=[motion(host.querySelector('.es-wheel'),[{transform:'rotate(0deg)'},{transform:'rotate(360deg)'}],2400)];tell('Пробный цикл: привод работает, лента движется.');host.querySelector('.es-belt')?.classList.add('es-running');}
   if(action==='test'){
    const group=host.querySelector('.es-cans');group.innerHTML=[0,1,2].map(i=>can(160,215,true,String(i+1),`class="es-test-can es-can-${i}"`)).join('');
    end=[...group.children].map((node,i)=>{node.style.opacity='0';const a=motion(node,[{transform:'translate(160px,215px)',opacity:0,offset:0},{transform:'translate(200px,213px)',opacity:1,offset:.1},{transform:`translate(${640+i*100}px,210px)`,opacity:1,offset:1}],2600,i*900);a.finished.then(()=>{if(!disposed){const c=host.querySelector('.es-counter');if(c)c.textContent=`${i+1} / 3`;}}).catch(()=>{});return a;});
    tell('Следи за проходом тары и сигналами датчика.');
   }
   try{await Promise.all(end.filter(Boolean).map(a=>a.finished));if(disposed)return;host.querySelector('.es-belt')?.classList.remove('es-running');busy=false;const area=host.querySelector('.es-actions');area.innerHTML=btn('next',action==='test'?'Осмотреть результат →':action==='baseline'?'Найти причину →':action==='install'?'Проверить зазор →':'Пустой цикл пройден →','es-primary');area.querySelector('button').focus({preventScroll:true});}catch{}
  }
  function controls(){switch(s.step){case 0:return btn('next','Начать смену →','es-primary');case 1:return s.checked.length===3?btn('next','Получить задание →','es-primary'):`<span>Изучено ${s.checked.length} из 3</span>`;case 3:return btn('baseline','Запустить модель →','es-primary');case 5:return btn('prepare','Подготовить макет с наставником →','es-primary');case 7:return btn('install','Установить направляющие →','es-primary');case 8:return `<label class="es-slider">Зазор <output>${s.gap}</output><input type="range" min="1" max="6" step="1" value="${s.gap}" aria-label="Зазор направляющих"></label>${btn('gap','Проверить настройку →','es-primary')}`;case 9:return s.chain.length===3?btn('next','К заданию на терминале →','es-primary'):btn('chainReset','Сбросить цепочку');case 11:return btn('dry','Проверить без продукции →','es-primary');case 12:return btn('test','Запустить три банки →','es-primary');case 13:return s.checked.length===3?btn('next','Записать результат →','es-primary'):`<span>Осмотрено ${s.checked.length} из 3</span>`;case 15:return btn('complete','Записать открытие в паспорт →','es-primary')+btn('restart','Пройти ещё раз');default:return '';}}
  function render(focus=false){const [id,scene,title,dialogue,instruction]=steps[s.step];
   const art=scene==='factory'?machine(s):scene==='bench'?bench(s):terminal(s);
   host.innerHTML=`<section class="es" data-step="${id}" data-scene="${scene}" aria-label="Инженерный участок"><header class="es-top"><a href="#map">← Завод</a><div><small>ИНЖЕНЕРНЫЙ УЧАСТОК</small><strong>${s.step<6?'01 / Разобраться':s.step<9?'02 / Переналадить':s.step<11?'03 / Согласовать':'04 / Проверить'}</strong></div><button data-es="pause" aria-pressed="false">Пауза</button></header><div class="es-world"><div class="es-scene-heading"><span>${s.step===0?'ТВОЯ ПЕРВАЯ ИНЖЕНЕРНАЯ ЗАДАЧА':'СМЕНА 01 · '+String(s.step).padStart(2,'0')}</span><h1 tabindex="-1">${title}</h1></div>${art}${s.step===0?'<div class="es-welcome-note">Одна новая банка.<br>Механика, автоматика<br>и твоя первая наладка.<small>8–10 минут · вместе с наставником</small></div>':''}${s.step===2?'<div class="es-order-note">НОВОЕ ЗАДАНИЕ <strong>Формат Б</strong>Широкая банка · комплект Б</div>':''}${s.step===15?'<div class="es-finish-note"><strong>Твоё инженерное открытие</strong><p>Изменить настройку — половина дела.<br>Нужно проверить результат и объяснить его команде.</p></div>':''}</div><div class="es-actions">${controls()}</div><div class="es-feedback" role="status" aria-live="polite"></div><section class="es-coach"><img src="assets/lab-guide-illustrated.png" alt="Наставник — огненный маскот Очаково"><div><span class="es-speaker">НАСТАВНИК</span><p>${dialogue}</p><strong>${instruction}</strong></div><button data-es="why" class="es-why">Об этой профессии ↗</button></section><footer class="es-footer">Учебная модель · параметры и устройство узла условные · без таймера и штрафов</footer><dialog class="es-dialog"><button data-es="close" class="es-close" aria-label="Закрыть">×</button><h2>Инженерный участок</h2><p>В кейсе «Очаково» отдельно названы автоматизация производственных линий и наладка технологического оборудования.</p><p>В описании практики среди возможных заданий по договорённости есть работа в паре с инженером технической поддержки, оцифровка линии и поиск улучшений производства.</p><p>В этой игре ты пробуешь общую логику такой работы. Узел, его параметры и конкретный случай придуманы для обучения.</p>${btn('close','Вернуться к задаче','es-primary')}</dialog></section>`;
   if(focus)host.querySelector('h1').focus({preventScroll:true});
  }
  function act(a){if(a==='pause'){paused=!paused;animations.forEach(n=>paused?n.pause():n.play());host.querySelector('.es').classList.toggle('es-paused',paused);const b=host.querySelector('[data-es=pause]');b.textContent=paused?'Продолжить':'Пауза';b.setAttribute('aria-pressed',String(paused));return;}if(paused)return;
   if(a==='why'){host.querySelector('dialog').showModal();return;}if(a==='close'){host.querySelector('dialog').close();return;}if(busy)return;
   const st=s.step;
   if(a==='restart'&&st===15){s={step:0,checked:[],chain:[],gap:2};save();render(true);return;}
   if(a==='complete'&&st===15){onComplete();return;}
   if(a==='next'&&([0,3,7,11,12].includes(st)||(st===1&&s.checked.length===3)||(st===9&&s.chain.length===3)||(st===13&&s.checked.length===3))){advance();return;}
   if(st===1&&['guides','sensor','motor'].includes(a)){if(!s.checked.includes(a))s.checked.push(a);save();render();tell({guides:'Направляющие удерживают банку на нужной траектории. Их геометрия зависит от формата тары.',sensor:'Датчик превращает появление банки в сигнал для системы управления.',motor:'Привод выполняет команду контроллера и двигает ленту.'}[a]);return;}
   if(st===2&&a.startsWith('format')){if(a==='formatB')advance();else tell('Это прежняя узкая банка. В новом задании указан широкий формат Б.');return;}
   if((st===3&&a==='baseline')||(st===7&&a==='install')||(st===11&&a==='dry')||(st===12&&a==='test')){run(a);return;}
   if(st===4&&['guides','sensor','motor'].includes(a)){if(a==='guides')advance();else tell(a==='sensor'?'Датчик видит банку. Посмотри, во что она упирается на входе.':'Привод работает. Причина связана с шириной прохода.');return;}
   if(st===5&&a==='prepare'){advance();tell('Наставник подготовил учебный макет. Можно подбирать оснастку.');return;}
   if(st===6&&a.startsWith('kit')){if(a==='kitB')advance();else tell('Комплект А рассчитан на узкую тару. Сопоставь ширину прохода с банкой Б.');return;}
   if(st===8&&a==='gap'){if(s.gap===4)advance();else tell(s.gap<4?'Проход слишком узкий. По учебной карточке нужна отметка 4.':'Зазор больше заданного. Направляющие должны удерживать траекторию; нужна отметка 4.');return;}
   if(st===9){if(a==='chainReset'){s.chain=[];save();render();return;}if(['sensor','controller','drive'].includes(a)){if(a===['sensor','controller','drive'][s.chain.length]){s.chain.push(a);save();render();tell(s.chain.length===3?'Цепочка собрана: обнаружить → обработать → выполнить.':'Верно. Какое устройство получает сигнал дальше?');}else tell('Сначала обнаружение, затем решение, затем движение. Подумай, какой узел нужен сейчас.');return;}}
   if(st===10&&a.startsWith('recipe')){if(a==='recipeB')advance();else tell('На макете установлен комплект Б. Программа должна соответствовать механической оснастке.');return;}
   if(st===13&&/^can[012]$/.test(a)){if(!s.checked.includes(a))s.checked.push(a);save();render();tell(`Банка ${Number(a.slice(-1))+1}: стоит ровно, следов повреждения нет. Проход без застревания.`);return;}
   if(st===14&&a.startsWith('record')){if(a==='recordGood')advance();else tell('В этой записи нет настройки и результата проверки. Следующей смене нужны конкретные сведения.');}
  }
  const click=e=>{const b=e.target.closest('[data-es]');if(b&&!b.disabled)act(b.dataset.es);};
  const keydown=e=>{if(e.target.matches('g[data-es]')&&['Enter',' '].includes(e.key)){e.preventDefault();act(e.target.dataset.es);}};
  const input=e=>{if(e.target.matches('.es-slider input')){s.gap=Number(e.target.value);save();host.querySelector('output').textContent=s.gap;host.querySelector('.es-front-guide').setAttribute('d',`M295 ${310+s.gap*12}h410v15H295Z`);}};
  host.addEventListener('click',click);host.addEventListener('keydown',keydown);host.addEventListener('input',input);render();
  return {destroy(){disposed=true;cancel();host.removeEventListener('click',click);host.removeEventListener('keydown',keydown);host.removeEventListener('input',input);},getState:()=>structuredClone(s)};
 }
 window.EngineeringStory={mount,steps:steps.map(x=>x[0])};
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('engineering-story.css?v=1',document.currentScript.src).href;document.head.append(css);
 const learned='Подобрал оснастку под новый формат тары, связал датчик, контроллер и привод, проверил учебный узел и записал результат переналадки.';
 Object.assign(window.OchakovoShift.roles.engineering,{role:'Наладка и автоматизация',lead:'Другой формат. Та же точность — первая инженерная задача вместе с наставником.',learned,day:'Инженерное направление в кейсе объединяет наладку оборудования и автоматизацию производственных линий. Важно понимать механическую часть, управление и способ проверки результата.',tools:'Оснастка, задание на переналадку, схема автоматики, терминал и журнал.',skills:'Наблюдательность, техническое мышление, точность и работа с наставником.'});
 Object.assign(window.GameMissions.list.find(x=>x.id==='engineering'),{minutes:9,role:'Наладка и автоматизация'});
 window.OchakovoShift.register('engineering',a=>{let game,finished=false;a.root.classList.add('engineering-story-shell');return {start(){game=mount(a.content,{onComplete(){finished=true;const b=document.createElement('button');b.hidden=true;b.dataset.do='finish';a.root.append(b);b.click();b.remove();}});},act(){},done:()=>finished,result:()=>({learned}),cleanup(){game?.destroy();},managesFocus:true};});
})();
